draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // body
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20 + 10*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.lineTo(W/2 - 30 + 10*Math.cos(t), H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.lineTo(W/2 + 30 - 10*Math.cos(t), H/2 - 20);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.lineTo(W/2 - 20, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.lineTo(W/2 + 20, H/2 + 60);
  ctx.stroke();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 5, H/2 + 10 + 10*Math.sin(t), 2, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 5, H/2 + 10 + 10*Math.sin(t), 2, 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
